"use client";

import { motion } from "motion/react";
import { cn } from "../../lib/cn.ts";

type Variant =
  | "default"
  | "secondary"
  | "destructive"
  | "red"
  | "blue"
  | "green"
  | "yellow"
  | "purple"
  | "pink"
  | "orange"
  | "cyan"
  | "indigo"
  | "violet"
  | "rose"
  | "amber"
  | "lime"
  | "emerald"
  | "sky"
  | "slate"
  | "fuchsia";

interface ShimmerTextProps {
  children: React.ReactNode;
  className?: string;
  variant?: Variant;
  duration?: number;
  delay?: number;
  spread?: number;
}

const variantMap: Record<Variant, string> = {
  default: "",
  secondary: "text-secondary-foreground",
  destructive: "text-destructive dark:text-destructive-foreground",
  red: "text-red-600 dark:text-red-400",
  blue: "text-blue-600 dark:text-blue-400",
  green: "text-green-600 dark:text-green-400",
  yellow: "text-yellow-600 dark:text-yellow-400",
  purple: "text-purple-600 dark:text-purple-400",
  pink: "text-pink-600 dark:text-pink-400",
  orange: "text-orange-600 dark:text-orange-400",
  cyan: "text-cyan-600 dark:text-cyan-400",
  indigo: "text-indigo-600 dark:text-indigo-400",
  violet: "text-violet-600 dark:text-violet-400",
  rose: "text-rose-600 dark:text-rose-400",
  amber: "text-amber-600 dark:text-amber-400",
  lime: "text-lime-600 dark:text-lime-400",
  emerald: "text-emerald-600 dark:text-emerald-400",
  sky: "text-sky-600 dark:text-sky-400",
  slate: "text-slate-600 dark:text-slate-400",
  fuchsia: "text-fuchsia-600 dark:text-fuchsia-400",
};

export function ShimmerText({
  children,
  className,
  variant = "default",
  duration = 1.5,
  delay = 1.5,
}: ShimmerTextProps) {
  return (
    <div className="group overflow-hidden">
      <div>
        <motion.div
          className={cn(
            "inline-block [--shimmer-contrast:rgba(255,255,255,0.6)] dark:[--shimmer-contrast:rgba(0,0,0,0.5)]",
            variantMap[variant],
            className,
          )}
          style={{
            WebkitTextFillColor: "transparent",
            background:
              "currentColor linear-gradient(to right, currentColor 0%, var(--shimmer-contrast) 40%, var(--shimmer-contrast) 60%, currentColor 100%)",
            WebkitBackgroundClip: "text",
            backgroundClip: "text",
            backgroundRepeat: "no-repeat",
            backgroundSize: "50% 200%",
          } as React.CSSProperties}
          initial={{
            backgroundPositionX: "250%",
          }}
          animate={{
            backgroundPositionX: ["-100%", "250%"],
          }}
          transition={{
            duration: duration,
            delay: delay,
            repeat: Infinity,
            repeatDelay: 1.5,
            ease: "linear",
          }}
        >
          <span>{children}</span>
        </motion.div>
      </div>
    </div>
  );
}

export default ShimmerText;

/**
 * Vendored from xxtomm/spell-ui (registry/spell-ui/bars-spinner.tsx) at fffe96db7b67. MIT licence, see ../../../ATTRIBUTION.md.
 * AICL: the `<style jsx>` block (needs styled-jsx, and its global `.bar`/`spin` names would leak)
 * is replaced by 12 motion bars with the same geometry (rotate + translate 146%) and a staggered opacity fade.
 */
"use client";

import * as React from "react";
import { motion } from "motion/react";
import { cn } from "../../lib/cn.ts";

interface BarsSpinnerProps extends React.HTMLAttributes<HTMLDivElement> {
  size?: number;
  color?: string;
}

const BARS = Array.from({ length: 12 }, (_, i) => i);

export const BarsSpinner = React.forwardRef<HTMLDivElement, BarsSpinnerProps>(
  ({ className, size = 20, color = "currentColor", style, ...props }, ref) => (
    <div
      ref={ref}
      role="presentation"
      className={cn("relative inline-block shrink-0", className)}
      style={{ width: size, height: size, ...style }}
      {...props}
    >
      <div className="absolute left-1/2 top-1/2 size-full">
        {BARS.map((i) => (
          <motion.div
            key={i}
            className="absolute rounded-[6px]"
            style={{
              background: color,
              height: "8%",
              left: "-10%",
              top: "-3.9%",
              width: "24%",
              transform: `rotate(${i === 0 ? 0.0001 : i * 30}deg) translate(146%)`,
            }}
            initial={{ opacity: 1 }}
            animate={{ opacity: [1, 0.15] }}
            transition={{ duration: 1.2, repeat: Infinity, ease: "linear", delay: -1.2 + i * 0.1 }}
          />
        ))}
      </div>
    </div>
  ),
);

BarsSpinner.displayName = "SpellUI.BarsSpinner";

export type { BarsSpinnerProps };
